from pathlib import Path
import json,hashlib,shutil,subprocess,base64
b=Path(__file__).resolve().parent.parent
notes={
'alpha-summary':('Rejected initial compute alpha summary','The initial compact-alpha candidate has a local HRESULT macro that shadows its input variable. MSVC warning C4700 exposed the invalid check; the exact-alpha probe failed before qualification. The first PowerShell wrapper failure is retained separately from the subsequent native probe failure. This candidate was never installed. See ../alpha-summary-fixed/README.md for the corrected implementation.'),
'alpha-summary-debug':('Unexecuted diagnostic alpha build','This diagnostic clone adds HRESULT logging but retains the initial macro defect. It was built and source hashes checked; no GPU probe or performance qualification was performed. It is not a deployable candidate.'),
'alpha-summary-fixed':('Corrected compute alpha summary','The corrected HRESULT macro has a unique local name; MSVC C4700/C4701 are build errors. A 33-frame GPU probe checks every alpha byte at 64×32, 67×35 and 6144×3456, four-slot queue capacity, all 256 byte values, one bottom-right 254 pixel, and opaque summary classification. Exact output passes. Opaque frames read only a 20,736-byte tile summary at 6K, while mixed frames preserve exact full alpha. Full-chain A/B/B/A uses direct-source disabled: performance did not show a repeatable overall gain, so this implementation remains experimental.'),
'alpha-summary-render':('Render-first alpha summary','This variant extracts R8_UNORM alpha using the existing render shader, then computes a compact tile summary from that plane. It avoids scattered R8_UINT UAV writes. The same 33-frame exact-alpha GPU probe passes. Full-chain A/B/B/A with the owned-source direct path improves repeated throughput, median and P95 versus that group\'s controls. Without direct submission, alpha summary alone does not establish a consistent latency gain. See transport/README.md via the parent folder for all measured values.'),
'direct-source-stop':('Owned-source direct submission and capture cleanup','A single tile covering the complete atlas can submit the owned source texture directly, avoiding the atlas clear and copy. Source mutex ownership spans encoder and alpha GPU submission; WGC still copies into an owned texture. The native destructor stops captures while the map retains strong source references. Four full-chain trials compare direct disabled/enabled on the same executable. Direct improves P95 in these samples, with slightly lower distinct throughput; it does not meet 60 ms. Later matched synthetic RGB checks and the integrated candidate lifecycle test cover this route; see ../candidate-quality/README.md and ../lifecycle-v2/README.md for their precise scopes. The earlier RT candidate had one teardown failure; the lifetime hazard was identified by code inspection, but that crash was not proven to have this cause.'),
'wgc-latest':('Bounded extra WGC frame drain','The callback tries at most one additional frame from its two-buffer pool. In the 30-second fixture run, all 1,513 callbacks report discarded=0. This workload provides no evidence for queued obsolete WGC frames or a benefit from the extra drain. No production WGC change was adopted.'),
'source-mmcss':('Reverse source main-thread MMCSS experiment','The native source main thread opts into Playback MMCSS HIGH through the existing helper; failure keeps ordinary scheduling. WGC callbacks and process/task priority are unchanged. The standalone run records registration and priority success, and AvRevert success on normal exit. Full-chain A/B/B/A separately forces direct-source disabled and compares only the MMCSS flag. No installed reverse binary has been changed.'),
'root-capture-stop':('Canonical capture lifetime cleanup build','The root App destructor now stops each capture while the source map retains strong references. This closes a teardown lifetime hazard found by inspection; it is not proof of the cause of the earlier 0xC0000409. This historical canonical 31-file snapshot built and passed all four Windows CTests. An earlier concurrent staging attempt received another candidate archive and was rejected by source hashes before build or execution; the retry uses a unique temporary archive. No installed reverse binary was replaced.')}
for name,(title,body) in notes.items():
 p=b/name;m=json.loads((p/'method/source-sha256.json').read_text());a=json.loads((p/'method/remote-source-sha256.json').read_text());assert m==a,(name,'remote source mismatch')
 assert all(hashlib.sha256((p/'source'/k).read_bytes()).hexdigest()==h for k,h in m.items()),name
 text=f'# {title}\n\n2026-09-09. {body}\n\nThe {len(m)} build-input files are archived under `source/`; local and remote SHA-256 maps agree. Build logs and actual probe status are retained in `method/`.\n'
 if (p/'summary.json').exists():
  s=json.loads((p/'summary.json').read_text());assert s['run_qualified'] and s['marker_validation']['decoded']==s['source_frames'] and s['marker_validation']['regressions']==0
  for f in ['record-probe-used.cpp','record-probe-used.json']:
   shutil.copy2(b/'mft-speed0/method'/f,p/'method'/f)
  v=s['marker_validation'];lat=s['stages_ms']['fixture_pre_draw_to_output'];text+=f"\nStandalone source run: {v['decoded']} decoded frames with exact opaque alpha, {v['steady_unique_hz']:.6f} distinct frames/s after warmup; pre-draw to local output median {lat['median']:.4f} ms, P95 {lat['p95']:.4f} ms. This excludes QUIC and Linux live presentation and is not an end-to-end acceptance result. All emitted frames decoded, normal bounded exit, no remaining candidate processes, and installed native hash unchanged.\n"
 if name=='source-mmcss':
  lines=(p/'runs/source.log').read_text(errors='replace').splitlines();reg=[x for x in lines if x.startswith('atlas-mmcss')];(p/'method/mmcss-events.json').write_text(json.dumps(reg,indent=2)+'\n');assert any('registered=1 priority_set=1' in x for x in reg) and any('reverted=1 error=0' in x for x in reg)
 if name in ['alpha-summary-fixed','alpha-summary-render']:
  assert json.loads((p/'method/alpha-exact-status.json').read_text())['exit']==0
  lines=(p/'method/alpha-exact.log').read_text();assert lines.count('alpha_async_exact ')==6 and lines.count('completed=4')==6 and lines.count('alpha_summary_exact ')==9
 if name=='wgc-latest':
  lines=(p/'runs/source.log').read_text(errors='replace').splitlines();events=[x for x in lines if x.startswith('wgc_latest ')];assert len(events)==1513 and all('discarded=0 ' in x for x in events)
 if name=='root-capture-stop':assert '100% tests passed, 0 tests failed out of 4' in (p/'method/build.log').read_text(errors='replace')
 (p/'README.md').write_text(text)
 files=sorted(f for f in p.rglob('*') if f.is_file() and '__pycache__' not in f.parts and f!=p/'sha256.json')
 (p/'sha256.json').write_text(json.dumps({str(f.relative_to(p)):hashlib.sha256(f.read_bytes()).hexdigest() for f in files},indent=2)+'\n');print(name,len(files))
